import {
  AfterContentInit,
  booleanAttribute,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  DoCheck,
  DOCUMENT,
  effect,
  ElementRef,
  forwardRef,
  inject,
  Injector,
  Input,
  input,
  model,
  OnInit,
  output,
  signal,
  viewChild,
  ViewEncapsulation,
} from '@angular/core';
import {
  ControlValueAccessor,
  FormGroupDirective,
  NG_VALUE_ACCESSOR,
  NgControl,
  NgForm,
} from '@angular/forms';
import {
  provideTranslocoScope,
  translateSignal,
  TranslocoModule,
  TranslocoService,
} from '@jsverse/transloco';
import { QTextHighlightDirective } from '@questrade/allspark-angular-components/core/directives';
import { QSharedResizeObserverService } from '@questrade/allspark-angular-components/core/services';
import {
  ENTER,
  ErrorState,
  injectDestroy,
  SPACE,
  voidFn,
} from '@questrade/allspark-angular-components/core/utils';
import { QDropdownOption } from '@questrade/allspark-angular-components/dropdown';
import {
  QDropmenuComponent,
  QDropmenuOriginDirective,
  QDropmenuSelectionChange,
} from '@questrade/allspark-angular-components/dropmenu';
import {
  ErrorStateMatcher,
  ErrorStateMatcherInterface,
  FormFieldControl,
} from '@questrade/allspark-angular-components/form-control';
import { QIconComponent, QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import {
  QInputDirective,
  QInputGroupComponent,
} from '@questrade/allspark-angular-components/input';
import { MISSING_KEY_HANDLER } from '@questrade/allspark-angular-components/transloco';
import { cancelOutline, chevronDown, search, thickCheck } from '@questrade/allspark-icons/icons';
import { debounceTime, takeUntil } from 'rxjs';
import { Q_COUNTRY_PICKER_COUNTRIES } from './country-picker-countries';
import { QCountryPickerCountryName } from './types/country-picker-country-name.type';
import { QCountryPickerCountry } from './types/country-picker-country.type';
import { QCountryPickerOptionDensity } from './types/country-picker-density.type';
import { QCountryPickerGroup } from './types/country-picker-group.type';
import { QCountryPickerIsoCode } from './types/country-picker-iso-code.type';

let nextUniqueId = 0;

@Component({
  selector: 'q-country-picker',
  templateUrl: './country-picker.component.html',
  styleUrls: ['./country-picker.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  host: {
    class: 'q-country-picker q-focus-indicator',
    '[class.q-country-picker-open]': 'dropmenuRef()?.isOpened',
    '[class.q-country-picker-error]': 'hasError() || errorState',
    '[class.q-fallback-emoji]': 'useFallbackEmojis',
    '[attr.id]': 'controlId',
    '[attr.data-qt]': 'dataQt()',
    '[attr.tabindex]': 'disabled ? -1 : 0',
    '[attr.disabled]': 'disabled || null',
    '[attr.readonly]': 'readonly() || null',
    '(click)': 'onHostClick()',
    '(keydown)': 'onHostKeydown($event)',
    '(blur)': 'onBlur()',
  },
  hostDirectives: [QDropmenuOriginDirective],
  imports: [
    QIconComponent,
    QInputDirective,
    QInputGroupComponent,
    QDropmenuComponent,
    TranslocoModule,
    QTextHighlightDirective,
  ],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => QCountryPickerComponent),
      multi: true,
    },
    { provide: FormFieldControl, useExisting: QCountryPickerComponent },
    provideTranslocoScope({ scope: 'allspark-country-picker' }),
    MISSING_KEY_HANDLER,
  ],
})
export class QCountryPickerComponent
  extends ErrorState
  implements OnInit, AfterContentInit, DoCheck, ControlValueAccessor, FormFieldControl
{
  readonly countrySelected = output<QCountryPickerCountry>();

  readonly value = model<QCountryPickerIsoCode>('');
  readonly density = input<QCountryPickerOptionDensity>('default');
  readonly readonly = input(false, { transform: booleanAttribute });
  readonly hasError = input(false, { transform: booleanAttribute });
  readonly visibleCountries = input<QCountryPickerCountryName[]>([]);
  readonly groups = input<QCountryPickerGroup[]>([]);
  readonly showTriggerFlag = input(true, { transform: booleanAttribute });
  readonly dataQt = input('q-country-picker');
  @Input({ transform: booleanAttribute }) disabled = false;
  @Input() override errorStateMatcher: ErrorStateMatcherInterface = new ErrorStateMatcher();

  protected readonly dropmenuRef = viewChild(QDropmenuComponent<QCountryPickerCountry>);
  protected readonly searchInput = viewChild<ElementRef<HTMLInputElement>>('searchInput');
  protected readonly clearIconRef = viewChild<ElementRef<HTMLElement>>('clearIconRef');

  controlId = `q-country-picker-${nextUniqueId++}`;
  searchPlaceholder = translateSignal('searchPlaceholder');
  searchEmptyStateMessage = translateSignal('searchEmptyStateMessage');
  triggerPlaceholder = translateSignal('triggerPlaceholder');
  countryOptions = signal<QDropdownOption<QCountryPickerCountry>[]>([]);
  /** @private */
  customHostElement: ElementRef<HTMLElement> | null = null;
  /** @private */
  showTriggerCountryName = true;
  /** @private */
  showTriggerCode = false;
  /** @private */
  showOptionCode = false;

  protected readonly dropmenuOrigin = inject(QDropmenuOriginDirective);
  protected useFallbackEmojis = false;
  protected selectedCountry: QCountryPickerCountry | null = null;
  protected filteredCountryOptions = signal<QDropdownOption<QCountryPickerCountry>[]>([]);
  protected dropmenuMinWidth = 168;
  protected searchValue = '';

  private _value: QCountryPickerIsoCode = '';
  private _onChange: (value: QCountryPickerIsoCode) => void = voidFn;
  private _onTouched: () => void = voidFn;
  private readonly _injector = inject(Injector);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _document = inject(DOCUMENT);
  private readonly _iconRegistry = inject(QIconRegistryService);
  private readonly _elementRef = inject(ElementRef);
  private readonly _resizeObserver = inject(QSharedResizeObserverService);
  private readonly _destroy$ = injectDestroy();
  private readonly _transloco = inject(TranslocoService);

  constructor() {
    super(inject(FormGroupDirective, { optional: true }), inject(NgForm, { optional: true }));

    this._registerIcons();

    effect(() => {
      const inputValue = this.value();
      if (inputValue !== this._value) {
        this._value = inputValue;
        this._updateSelectedCountryFromValue();
        this._cdr.markForCheck();
      }
    });

    effect(() => {
      const hasError = this.hasError();
      this.errorState = hasError;
      this.stateChanges.next();
    });
  }

  ngOnInit(): void {
    this._setFallbackEmojis();
    this._setComponentControl();
    this._subscribeToStateChanges();
    this._disableDropmenuTypeahead();
  }

  ngAfterContentInit(): void {
    this._transloco
      .selectTranslation('allspark-country-picker')
      .pipe(takeUntil(this._destroy$))
      .subscribe((translations) => this._handleTranslationChange(translations));

    this._handleWidthChanges();
  }

  ngDoCheck(): void {
    this._updateErrorState();
  }

  onBlur(): void {
    this._onTouched();
  }

  writeValue(value: QCountryPickerIsoCode): void {
    this._value = value;
    this.value.set(value);
    this._updateSelectedCountryFromValue();
    this._cdr.markForCheck();
  }

  registerOnChange(fn: (value: QCountryPickerIsoCode) => void): void {
    this._onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this._onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabled = isDisabled;
    this._cdr.markForCheck();
  }

  protected onHostClick(): void {
    if (!this.disabled && !this.readonly()) {
      this.dropmenuRef()?.open();
    }
  }

  protected onHostKeydown(event: KeyboardEvent): void {
    if (this.disabled || this.readonly()) return;

    if ([SPACE, ENTER].includes(event.code) && !this.dropmenuRef()?.isOpened) {
      event.stopImmediatePropagation();
      this.dropmenuRef()?.open();
    }
  }

  protected onDropmenuChange(event: QDropmenuSelectionChange<QCountryPickerCountry>): void {
    const selectedValue = event.option.value;

    if (!selectedValue?.isoCode) return;

    this.selectedCountry = selectedValue;
    this._value = selectedValue.isoCode;

    this._onChange(this._value);
    this.value.set(this._value);
    this.countrySelected.emit(this.selectedCountry);
  }

  protected onDropmenuOpened(): void {
    this.searchInput()?.nativeElement.focus();
    this._setDropmenuWidth();
  }

  protected onDropmenuClosed(): void {
    this.searchValue = '';
    this.clearSearch();
  }

  protected onSearchInput(event: Event): void {
    this.searchValue = (event.target as HTMLInputElement).value;
    this._filterCountries();
    setTimeout(() => {
      this.dropmenuRef()?.resetActiveAfterOptionsChange();
    });
  }

  protected clearSearch(): void {
    const searchInputEl = this.searchInput();
    if (searchInputEl) {
      this.searchValue = '';
      searchInputEl.nativeElement.value = '';
      this._filterCountries();
      searchInputEl.nativeElement.focus();
      this._cdr.markForCheck();
    }
  }

  protected showClearIcon(): boolean {
    return !!this.searchInput() && !!this.dropmenuRef()?.isOpened && !!this.searchValue;
  }

  private _findSelectedCountryByIsoCode(isoCode: string): QCountryPickerCountry | null {
    return (
      this.countryOptions().find((country) => country.value.isoCode === isoCode)?.value ?? null
    );
  }

  private _registerIcons(): void {
    this._iconRegistry.registerIcons([chevronDown, search, cancelOutline, thickCheck]);
  }

  private _setFallbackEmojis(): void {
    this.useFallbackEmojis = !this._platformSupportsEmojis();
  }

  private _setComponentControl(): void {
    const ngControl = this._injector.get(NgControl, null, { optional: true });
    if (ngControl) {
      this.ngControl = ngControl;
    }
  }

  private _updateSelectedCountryFromValue(): void {
    const isoCode = this._value || this.value();
    this.selectedCountry = this._findSelectedCountryByIsoCode(isoCode);
  }

  private _subscribeToStateChanges(): void {
    this.stateChanges.pipe(takeUntil(this._destroy$)).subscribe(() => {
      this._cdr.markForCheck();
    });
  }

  private _disableDropmenuTypeahead(): void {
    const dropmenu = this.dropmenuRef();
    if (dropmenu) {
      dropmenu._withTypeahead = false;
    }
  }

  /**
   * Checks if the current platform supports emojis.
   *
   * This method creates a canvas element and draws an emoji on it. It then checks the pixel data of the emoji
   * to determine if the platform supports emojis. If the pixel data is not all zeros, it indicates that the
   * platform supports emojis. This technique is commonly used to detect emoji support in web browsers, as
   * some browsers may not support all emojis or may render them differently.
   *
   */
  private _platformSupportsEmojis(): boolean {
    const FONT_FAMILY =
      '"Twemoji Mozilla","Apple Color Emoji","Segoe UI Emoji","Segoe UI Symbol",' +
      '"Noto Color Emoji","EmojiOne Color","Android Emoji",sans-serif';

    const canvas = this._document.createElement('canvas');
    canvas.width = canvas.height = 1;
    const canvasContext = canvas.getContext('2d', { willReadFrequently: true });
    if (!canvasContext) return false;

    canvasContext.textBaseline = 'top';
    canvasContext.font = `100px ${FONT_FAMILY}`;
    canvasContext.scale(0.01, 0.01);
    canvasContext.clearRect(0, 0, 100, 100);
    canvasContext.fillStyle = '#000';
    canvasContext.fillText('🇨🇦', 0, 0);

    const pixelRGBAArray = canvasContext.getImageData(0, 0, 1, 1).data;
    const emojiColor = pixelRGBAArray.join(',');

    return !emojiColor.startsWith('0,0,0,');
  }

  private _createCountryOptions(
    translations: Record<string, QCountryPickerCountryName>,
  ): QDropdownOption<QCountryPickerCountry>[] {
    const visible = this.visibleCountries();
    return Q_COUNTRY_PICKER_COUNTRIES.filter(
      (country) => !visible?.length || visible.includes(country.name),
    )
      .map((country) => {
        const translationKey = 'countries.' + country.isoCode;
        const displayName = translations[translationKey] || country.name;

        const groupProp = this._getCountryGroupProp(country.name);
        return {
          label: displayName,
          value: {
            ...country,
            ...groupProp,
            name: displayName,
          },
        };
      })
      .sort((a, b) => a.label.localeCompare(b.label));
  }

  private _getCountryGroupProp(name: QCountryPickerCountryName): Partial<QCountryPickerCountry> {
    const countryGroup = this.groups()?.find((group) => group.countries.includes(name));
    return { ...(countryGroup && { groupId: countryGroup?.id }) };
  }

  private _handleWidthChanges(): void {
    const host = this.customHostElement?.nativeElement || this._elementRef.nativeElement;
    let previousWidth = host.offsetWidth;

    this._resizeObserver
      .observe(host)
      ?.pipe(debounceTime(300), takeUntil(this._destroy$))
      .subscribe(() => {
        const currentWidth = host.offsetWidth;

        if (currentWidth !== previousWidth) {
          previousWidth = currentWidth;
          this._setDropmenuWidth();
        }
      });
  }

  private _setDropmenuWidth(): void {
    const host = this.customHostElement?.nativeElement || this._elementRef.nativeElement;
    const hostWidth = host.offsetWidth;
    this.dropmenuMinWidth = hostWidth;

    const dropmenu = this.dropmenuRef();
    if (dropmenu) {
      const dropmenuElement = dropmenu._getDropmenuHostElement();
      dropmenuElement.style.setProperty('--awds-dropmenu-container-width', `${hostWidth}px`);
    }
  }

  private _handleTranslationChange(translations: Record<string, QCountryPickerCountryName>): void {
    this.countryOptions.set(this._createCountryOptions(translations));
    this.filteredCountryOptions.set(this.countryOptions());
    this._updateSelectedCountryFromValue();
    this._cdr.markForCheck();
  }

  private _filterCountries(): void {
    if (!this.searchValue) {
      this.filteredCountryOptions.set(this.countryOptions());
      return;
    }

    const searchLower = this.searchValue.toLowerCase();
    const filtered = this.countryOptions().filter(
      (country) =>
        country.label.toLowerCase().includes(searchLower) ||
        country.value.code.includes(searchLower),
    );
    this.filteredCountryOptions.set(filtered);
  }
}
